use vstd::prelude::*;

verus! {
    fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32>
        requires
            a.len() == mask.len(),
            !values.is_empty(),
    ensures
        result.len() == a.len(),
        forall(|i: nat| i < a.len() as nat ==> (mask[i as usize] ==> result[i as usize] == values[(i % values.len() as nat) as usize]) && (!mask[i as usize] ==> result[i as usize] == a[i as usize])),
    {
        assert_eq!(a.len(), mask.len(), "Input array and mask must have the same length.");
        assert!(!values.is_empty(), "Replacement values array must not be empty.");

        let mut result = Vec::with_capacity(a.len());

        for i in 0..a.len()
            invariant
                i <= a.len(),
                result.len() == i,
                forall(|j: nat| j < i as nat ==> (mask[j as usize] ==> result[j as usize] == values[(j % values.len() as nat) as usize]) && (!mask[j as usize] ==> result[j as usize] == a[j as usize])),
            decreases a.len() - i,
        {
            if mask[i] {
                // Use the replacement value at index i modulo the length of values
                result.push(values[i % values.len()]);
            } else {
                // Use the original value from the input array
                result.push(a[i]);
            }
        }

        result
    }
}

